import java.util.*; import java.io.*; public class Main { static final long MOD = 1000000007; static final long PHI = 1000000006; public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); long[] A = new long[100001]; long[] prefixSum = new long[100001]; int count = 1; outer: for (int len = 1; ; len += 2) { int half = (len + 1) / 2; int start = (int) Math.pow(10, half - 1); int end = (int) Math.pow(10, half) - 1; for (int i = start; i <= end; i++) { String s = String.valueOf(i); StringBuilder sb = new StringBuilder(s); String rev = new StringBuilder(s.substring(0, len / 2)).reverse().toString(); sb.append(rev); A[count] = Long.parseLong(sb.toString()); prefixSum[count] = (prefixSum[count - 1] + A[count]) % PHI; if (count == 100000) break outer; count++; } } String line = br.readLine(); if (line != null) { int Q = Integer.parseInt(line.trim()); while (Q-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int L = Integer.parseInt(st.nextToken()); int R = Integer.parseInt(st.nextToken()); long exponent = (prefixSum[R] - prefixSum[L] + PHI) % PHI; out.println(power(A[L], exponent)); } } out.flush(); out.close(); } static long power(long base, long exp) { long res = 1; base %= MOD; while (exp > 0) { if (exp % 2 == 1) res = (res * base) % MOD; base = (base * base) % MOD; exp /= 2; } return res; } }